function resizeModel(){if(!modelOpen)return;const b=$('modelStage').getBoundingClientRect(),dpr=Math.min(window.devicePixelRatio||1,3);const c=$('modelCanvas');c.width=Math.max(1,Math.round(b.width*dpr));c.height=Math.max(1,Math.round(b.height*dpr));drawModel()}
function drawModel(){if(!modelOpen||!p())return;const c=$('modelCanvas'),rect=$('modelStage').getBoundingClientRect(),w=rect.width,h=rect.height;if(w<1||h<1)return;const ctx=c.getContext('2d'),dpr=Math.min(window.devicePixelRatio||1,3);ctx.setTransform(dpr,0,0,dpr,0,0);ctx.clearRect(0,0,w,h);const count=Object.keys(head().floors).length,spread=modelExplode?7.4:3.8;const scale=Math.min(w/43,h/(30+count*spread*.9));const zcenter=(count-1)*spread/2;function proj(pt){const [x,y,z]=pt,xx=x*Math.cos(modelYaw)-y*Math.sin(modelYaw),yy=x*Math.sin(modelYaw)+y*Math.cos(modelYaw);return [w/2+xx*scale,h/2+(yy*Math.cos(modelPitch)-(z-zcenter)*Math.sin(modelPitch))*scale,yy*Math.sin(modelPitch)+(z-zcenter)*Math.cos(modelPitch)]}let faces=[];function cube(x,y,z,dx,dy,dz,fill,stroke){const v=[[x,y,z],[x+dx,y,z],[x+dx,y+dy,z],[x,y+dy,z],[x,y,z+dz],[x+dx,y,z+dz],[x+dx,y+dy,z+dz],[x,y+dy,z+dz]].map(proj);const fs=[[0,1,2,3],[0,1,5,4],[1,2,6,5],[2,3,7,6],[3,0,4,7],[4,5,6,7]];fs.forEach((idx,i)=>faces.push({p:idx.map(j=>v[j]),depth:idx.reduce((a,j)=>a+v[j][2],0)/4,fill:i===5?fill[0]:i===2||i===3?fill[1]:fill[2],stroke}))}const activeIndex=Object.keys(head().floors).indexOf(activeFloor);for(let l=0;l<count;l++){let z=l*spread,hi=l===activeIndex;cube(-13,-9,z,26,18,.3,hi?['#dceee6','#97b6a6','#bacfc4']:['#edf1ef','#c5d0c9','#dce2dd'],'#9fb4a7');const wc=hi?['#f8fcfa','#adc6b8','#d4e3da']:['#fafcfb','#bdccc3','#e2eae5'];const wallH=2.7;cube(-13,-9,z+.3,26,.19,wallH,wc,'#9bb2a2');cube(-13,8.8,z+.3,26,.19,wallH,wc,'#9bb2a2');cube(-13,-9,z+.3,.19,18,wallH,wc,'#9bb2a2');cube(12.8,-9,z+.3,.19,18,wallH,wc,'#9bb2a2');for(const x of [-6.5,0,6.5]){cube(x,-9,z+.3,.14,7.5,wallH,wc,'#a8bcaf');cube(x,1.5,z+.3,.14,7.4,wallH,wc,'#a8bcaf')}for(const yy of [-1.5,1.5])for(let i=0;i<4;i++){cube(-13+i*6.5,yy,z+.3,2,.14,wallH,wc,'#a8bcaf');cube(-9.8+i*6.5,yy,z+.3,3.1,.14,wallH,wc,'#a8bcaf')}for(let i=0;i<4;i++){cube(-13+i*6.5,-4,z+.3,6.5,.12,wallH,wc,'#a8bcaf');cube(-13+i*6.5,4,z+.3,6.5,.12,wallH,wc,'#a8bcaf')}for(let x of [-4.8,-2.6,1.2,3.4,7.6,9.8]){cube(x,5.4,z+.3,.8,2,1.4,['#dae7e8','#9bb8bd','#bad1d2'],'#90b0b6')}for(let j=0;j<10;j++){cube(-11.8,-8+j*.29,z+.3,3,.3,.18*(j+1),['#f8faf7','#a5b8a7','#d2ded2'],'#acc0ac')}}faces.sort((a,b)=>a.depth-b.depth);for(const f of faces){ctx.beginPath();f.p.forEach((v,i)=>i?ctx.lineTo(v[0],v[1]):ctx.moveTo(v[0],v[1]));ctx.closePath();ctx.fillStyle=f.fill;ctx.fill();ctx.strokeStyle=f.stroke;ctx.lineWidth=.55;ctx.stroke()}for(let l=0;l<count;l++){const q=proj([-15,-9,l*spread+.5]);ctx.fillStyle=l===activeIndex?'#087f75':'#8b9f92';ctx.font='11px monospace';ctx.fillText(Object.values(head().floors)[l].label,q[0]-20,q[1])}ctx.fillStyle='#a0b0a7';ctx.font='10px sans-serif';ctx.fillText('ILLUSTRATION ONLY',18,h-23)}
function bind(){document.querySelectorAll('[data-home]').forEach(b=>b.onclick=e=>{e.preventDefault();goHome()});document.querySelectorAll('[data-action="help"]').forEach(b=>b.onclick=help);$('newProject').onclick=newProjectDialog;$('projectSearch').oninput=renderHome;$('backHome').onclick=goHome;$('projectMenu').onclick=projectPop;$('floorBtn').onclick=floorPop;$('moreBtn').onclick=morePop;$('historyBtn').onclick=$('revisionBtn').onclick=()=>openDrawer('history');$('issuesBtn').onclick=()=>openDrawer(allItems().some(o=>o.status==='pending')?'issues':'objects');$('recognizeBtn').onclick=recognize;$('generateBtn').onclick=preflight;$('stepSource').onclick=openSources;$('stepReview').onclick=()=>{if(!p())return;guardDraft(()=>{modelOpen=false;$('modelArea').classList.add('hidden');$('resultRibbon').classList.add('hidden');updateUI();requestAnimationFrame(()=>{resize();fitView()})})};$('stepResult').onclick=openResults;document.querySelectorAll('[data-tool]').forEach(b=>b.onclick=()=>setTool(b.dataset.tool));$('undoBtn').onclick=undo;$('redoBtn').onclick=redo;$('overlayBtn').onclick=()=>{showOverlay=!showOverlay;$('overlayBtn').classList.toggle('active',showOverlay);$('overlayBtn').setAttribute('aria-pressed',String(showOverlay));queueDraw()};$('zoomIn').onclick=()=>zoom(1.2);$('zoomOut').onclick=()=>zoom(1/1.2);$('fitBtn').onclick=fitView;$('emptyUpload').onclick=()=>{uploadTarget=activeId;$('imageInput').click()};$('projectInput').onchange=()=>{const file=$('projectInput').files[0];$('projectInput').value='';if(file)importProject(file)};$('imageInput').onchange=()=>{const files=[...$('imageInput').files];$('imageInput').value='';if(uploadTarget&&uploadTarget!==activeId){toast('项目已切换，请重新选择文件。',true);return}upload(files)};$('closeModel').onclick=()=>{modelOpen=false;$('modelArea').classList.add('hidden');updateUI();requestAnimationFrame(()=>{resize();fitView()})};$('explodeBtn').onclick=()=>{modelExplode=!modelExplode;$('explodeBtn').innerHTML=ic('layers')+(modelExplode?'还原装配':'分层展开');drawModel()};$('modelReset').onclick=()=>{modelYaw=-.70;modelPitch=.72;drawModel()};const mc=$('modelCanvas');mc.onpointerdown=e=>{mc.setPointerCapture(e.pointerId);modelDrag={x:e.clientX,y:e.clientY,yaw:modelYaw,pitch:modelPitch}};mc.onpointermove=e=>{if(!modelDrag)return;modelYaw=modelDrag.yaw+(e.clientX-modelDrag.x)*.008;modelPitch=clamp(modelDrag.pitch+(e.clientY-modelDrag.y)*.005,.2,1.25);drawModel()};mc.onpointerup=mc.onpointercancel=()=>modelDrag=null;
const canvas=$('planCanvas');canvas.addEventListener('pointerdown',pointerDown);canvas.addEventListener('pointermove',pointerMove);canvas.addEventListener('pointerup',e=>pointerUp(e));canvas.addEventListener('pointercancel',e=>pointerUp(e,true));canvas.addEventListener('lostpointercapture',e=>{if(gesture)pointerUp(e,true)});canvas.addEventListener('wheel',e=>{e.preventDefault();const r=canvas.getBoundingClientRect();zoom(Math.exp(-e.deltaY*.0014),e.clientX-r.left,e.clientY-r.top)},{passive:false});document.addEventListener('pointerdown',e=>{if($('popoverRoot').children.length&&!$('popoverRoot').contains(e.target)&&!['projectMenu','floorBtn','moreBtn'].some(id=>$(id).contains(e.target)))closePop()});window.addEventListener('resize',()=>{resize();closePop()});new ResizeObserver(()=>resize()).observe($('stage'));window.addEventListener('blur',()=>{gesture=null;space=false;queueDraw()});document.addEventListener('keydown',e=>{if($('modalRoot').children.length){if(e.key==='Escape'){e.preventDefault();closeModal()}if(e.key==='Tab'){const els=[...$('modalRoot').querySelectorAll('button:not(:disabled),input:not(:disabled),select,textarea,a[href]')].filter(el=>el.offsetParent!==null),first=els[0],last=els.at(-1);if(e.shiftKey&&document.activeElement===first){last.focus();e.preventDefault()}else if(!e.shiftKey&&document.activeElement===last){first.focus();e.preventDefault()}}return}if(e.key==='Escape'){e.preventDefault();if($('popoverRoot').children.length)closePop();else if(draft)cancelDraft(true);else if(drawer)closeDrawer();else if(tool!=='select'){tool='select';setTool('select')}return}if(['INPUT','TEXTAREA','SELECT'].includes(document.activeElement?.tagName)||screen!=='workspace')return;if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='z'){e.preventDefault();e.shiftKey?redo():undo();return}if(e.code==='Space'){e.preventDefault();space=true;return}if(e.ctrlKey||e.metaKey||e.altKey)return;const k=e.key.toLowerCase();if({v:'select',r:'rect',h:'pan'}[k])setTool({v:'select',r:'rect',h:'pan'}[k]);if(k==='f')fitView();if(k==='o')$('overlayBtn').click()});document.addEventListener('keyup',e=>{if(e.code==='Space')space=false});window.addEventListener('pagehide',persist);window.addEventListener('beforeunload',e=>{if(isDirty()){e.preventDefault();e.returnValue=''}});
let dragCount=0;const ws=$('workspace');ws.addEventListener('dragover',e=>{e.preventDefault()});ws.addEventListener('dragenter',e=>{e.preventDefault();dragCount++;ws.classList.add('drag-active')});ws.addEventListener('dragleave',e=>{dragCount--;if(dragCount<=0)ws.classList.remove('drag-active')});ws.addEventListener('drop',e=>{e.preventDefault();dragCount=0;ws.classList.remove('drag-active');const files=[...e.dataTransfer.files];guardDraft(()=>upload(files))})}
async function init(){bind();try{db=await openDB();const stored=await new Promise((res,rej)=>{const tx=db.transaction('workspaces','readonly');const r=tx.objectStore('workspaces').get('state');r.onsuccess=()=>res(r.result);r.onerror=()=>rej(r.error)});if(stored&&stored.schema===SCHEMA&&Array.isArray(stored.projects)&&stored.projects.length){state=stored;for(const pr of state.projects)for(const r of pr.runs)if(r.status==='running'){r.status='interrupted';event(pr,'demo.interrupted','页面重开，未完成演示标记为中断',{run:r.id,modelExecuted:false})}}else seed()}catch(e){db=null;seed()}renderHome();document.body.dataset.ready='true'}
